import { fill } from "./fill";
import type { TextLocale } from "./checkboxes";

/**
 * Fixed prelude spoken to the adult who answers (docs/legal/textos/03, section B). NOT generated by a model.
 * Exact texts, version legal-v1.3 (D20; D13 kept the AI disclosure to the adult, D20 shortened it). Santa is implemented; other characters are added as new entries
 * (Reyes, Rex, Perez: section B2/B3) without touching the engine.
 */
export interface PreludeTexts {
  /** Version id stored with every call, e.g. 03-SANTA-es-419-legal-v1.3. */
  id: string;
  /** Step 3: main notice (D20: about 10 s). Its last part (from `mainOpenFrom`) equals `repeat`. */
  main: string;
  /**
   * D14: where the interruptible part of `main` starts. Everything before this marker (who calls, that it is an AI voice,
   * why, that it is not a person, that the call will be recorded) is played without barge-in; the key instructions after it
   * accept a key pressed while they play. Must occur exactly once in `main`.
   */
  mainOpenFrom: string;
  /** Step 4: repeat, only the last sentence. */
  repeat: string;
  /** D14: same as `mainOpenFrom` for `handoff`. D20: null = the whole hand-off is interruptible (it carries no notice any more). */
  handoffOpenFrom: string | null;
  /** Step 5, key 1: hand-off to the child. */
  handoff: string;
  /** Step 7: repeated once after 30 s without the second key. */
  handoffRepeat: string;
  /** Step 5, key 2. */
  optout: string;
  /** Step 4, no key after the repeat. */
  noResponse: string;
  /** Step 6: any other key. */
  pressOne: string;
  /** First line of the character after the second key 1. */
  firstLine: string;
  /** Fixed closing phrase (B4 / D-02) if the model runs out of time. */
  closing: string;
  /**
   * D20: pre-recorded clips (public paths) for `main` (locked notice + interruptible key instructions, which also serve as
   * `repeat`) and `handoff`. Played with <Play>, with the child's name spoken by the telephony voice between two clips;
   * `main`/`repeat`/`handoff` text stays the source of truth (and the fallback <Say>).
   */
  audio?: PreludeAudio;
}

export interface PreludeAudio {
  /** Played without barge-in. Parts starting with "/" are clips; other parts are spoken text (the child's name). */
  mainLocked: string[];
  /** Key instructions, inside the <Gather>; also the clip used for the repeat. */
  mainOpen: string;
  handoff: string[];
}

/** Version of the text package. Santa text ids carry the "-legal-v1.3" suffix (03 section H). */
export const PRELUDE_VERSION = "legal-v1.3";

const AUDIO_BASE = "/audio/prelude";
const clip = (locale: TextLocale, name: string) => `${AUDIO_BASE}/${locale}/${name}.mp3`;
/**
 * Pre-recorded clips (warm "North Pole helper" catalog voice, never Santa's). A part that does not start with "/" is spoken
 * with the telephony voice (<Say>), which is how the child's name is inserted between two clips.
 */
const audioFor = (locale: TextLocale): PreludeAudio => ({
  mainLocked: [clip(locale, "main-a"), "{{NOMBRE_NIÑO}}", clip(locale, "main-b")],
  mainOpen: clip(locale, "open"),
  handoff: [clip(locale, "handoff-a"), "{{NOMBRE_NIÑO}}", clip(locale, "handoff-b")],
});

